"""A Level Physics (Lower Sixth, 0780): quantities, mechanics, circular and rotational motion. Practice sets."""

from .dsl import *  # noqa: F403

COURSE = ("physics", "lower-sixth")

M1 = "Physical Quantities, Dimensional Analysis & Uncertainties"
M2 = "Kinematics, Linear Dynamics & Collisions"
M3 = "Statics, Work, Energy, Circular & Rotational Motion"

SETS = []


def mcq(prompt, opts, ans, whys, steps, concept, skill, hint, fb="", diagram="", alt=""):
    """4-option MC: `ans` is the index of the correct option; `whys` has one entry per option (ignored for the correct one)."""
    ch = [C(o, correct=(i == ans), why=("" if i == ans else whys[i])) for i, o in enumerate(opts)]
    return MC(prompt, ch, steps, concept=concept, skill=skill, hint=hint, feedback=fb, diagram=diagram, diagram_alt=alt)

