            [r"That is the angular momentum $I\omega$ ($8$), not the energy.", "", r"You left out the factor $\tfrac12$.", "That is ten times too large: half of 0.80 times 100 is 40."],
            [S("Rotational kinetic energy", math=r"\tfrac12I\omega^2 = \tfrac12(0.80)(100) = 40\ \mathrm{J}")],
